///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
        txb_pISU_NM.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
