///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_Search
 * @description 종목조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_BefIsuInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_BefIsuInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_ChangeProc
 * @description 변경처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_ChangeProc = async function() {
    // 사전체크
    if (!await scwin.chkValid("change")) {
        return;
    }
    if (!confirm("변경하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/EtcInfoAction.do",
        ref : "dts_AftIsuInfo",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {

};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {

};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_BefIsuInfo.removeAll();
    dts_AftIsuInfo.removeAll();
    txb_ISU_NM.setValue("");
    txb_ISU_ABBRV.setValue("");
    txb_ISU_ENG_NM.setValue("");
    txb_ISU_ENG_ABBRV.setValue("");
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "select") {
        if (txb_SRCH_ISUR_CD.getValue() === "") {
            await $c.win.alert("발행기관 코드를 입력하세요.");
            txb_SRCH_ISUR_CD.focus();
            return false;
        }
    } else if (pGubun === "batchChange") {
        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_BefIsuInfo.getRowCount(); nRow++) {
            if (dts_BefIsuInfo.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 종목이 없습니다.");
            return false;
        }
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("발행기관 코드를 입력하세요.");
            txb_ISUR_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "") {
            await $c.win.alert("기준명을 입력하세요.");
            return false;
        }
    } else if (pGubun === "change") {
        // 처리 대상이 존재 하는지..
        if (dts_AftIsuInfo.getRowCount() < 1) {
            await $c.win.alert("처리대상 종목이 존재하지 않습니다.");
            return false;
        }

        // 종목명 체크
        for (let nRow = 1; nRow <= dts_AftIsuInfo.getRowCount(); nRow++) {
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_NM")) === "") {
                await $c.win.alert("한글기준명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ABBRV")) === "") {
                await $c.win.alert("한글기준약명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ENG_NM")) === "") {
                await $c.win.alert("영문기준명을 입력하세요.");
                return false;
            }
            if ($c.stf.trim(dts_AftIsuInfo.getCellData(nRow, "ISU_ENG_ABBRV")) === "") {
                await $c.win.alert("영문기준약명을 입력하세요.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name getParam
 * @description 발생기관 팝업에서 값 받음.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name batchChange
 * @description 일괄적용
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.batchChange = async function() {
    // 일괄적용 사전체크
    if (!await scwin.chkValid("batchChange")) {
        return;
    }

    // 헤더정보 복사
    $c.stf.copyDataSetHeader(dts_BefIsuInfo, dts_AftIsuInfo);

    // row Copy
    scwin.copyRow();
};

/**
 * @method
 * @name copyRow
 * @description 데이터셋 RowCopy
 * @returns {void}
 * @hidden N
 */
scwin.copyRow = function() {
    grd_AftIsuInfo.ReDraw = false;
    dts_AftIsuInfo.setBroadcast(false);
    for (let nRow = 1; nRow <= dts_BefIsuInfo.getRowCount(); nRow++) {
        if (dts_BefIsuInfo.getCellData(nRow, "CHK") === "T") {
            dts_AftIsuInfo.insertRow();
            const nLastRow = dts_AftIsuInfo.getRowCount();
            dts_AftIsuInfo.setCellData(nLastRow, "STD_CD", dts_BefIsuInfo.getCellData(nRow, "STD_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_NM", txb_ISU_NM.getValue());
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ABBRV", txb_ISU_ENG_NM.getValue());
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ENG_NM", txb_ISU_ABBRV.getValue());
            dts_AftIsuInfo.setCellData(nLastRow, "ISU_ENG_ABBRV", txb_ISU_ENG_ABBRV.getValue());
            dts_AftIsuInfo.setCellData(nLastRow, "UNQ_ISU_NM", dts_BefIsuInfo.getCellData(nRow, "UNQ_ISU_NM"));
            dts_AftIsuInfo.setCellData(nLastRow, "UNQ_ISU_ENG_NM", dts_BefIsuInfo.getCellData(nRow, "UNQ_ISU_ENG_NM"));
            dts_AftIsuInfo.setCellData(nLastRow, "LIST_STAT_CD", dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "ACTIV_TP_CD", dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD"));
            dts_AftIsuInfo.setCellData(nLastRow, "KIND", dts_BefIsuInfo.getCellData(nRow, "KIND"));
            dts_AftIsuInfo.setCellData(nLastRow, "ISUR_CD", txb_ISUR_CD.getValue());
            dts_AftIsuInfo.setCellData(nLastRow, "LIST_STAT_NM", dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_NM"));
        }
    }
    dts_AftIsuInfo.setBroadcast(true, true);
    grd_AftIsuInfo.ReDraw = true;
};

/**
 * @method
 * @name isAbleChk
 * @description 체크가 가능한지 체크 1. 채권은 상장이면 체크 불가 2. 비활성은 체크 불가
 * @param {*} nRow nRow
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isAbleChk = async function(nRow, bCheck) {
    if (bCheck === 0) {
        return;
    }

    // 3 주식워런트 체크(주식워런트 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "KIND") === "주식워런트") {
        await $c.win.alert("주식워런트는 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
    // ETN 체크(ETN 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "KIND") === "ETN") {
        await $c.win.alert("ETN은 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }

    // 1. 채권은 상장이면 체크 불가. ->     모든 상장인경우 변경불가  F-226  2013.11.14
    // var tmpStdCd = dts_BefIsuInfo.NameString(nRow, "STD_CD").substr(0, 3);
    // if( tmpStdCd == "KR1" || tmpStdCd == "KR2" || tmpStdCd == "KR3" || tmpStdCd == "KR6" || tmpStdCd == "KRB"){
    // if( dts_BefIsuInfo.NameString(nRow, "KIND") == "채권" ){        모든 상장인경우 변경불가  F-226  2013.11.14
    if (dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD") === "Y") {
        await $c.win.alert("상장여부 \"상장\"인 경우 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
    // }

    // 2. 활성여부 체크(비활성은 체크 불가)
    if (dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") !== "Y" && dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") !== "1") {
        await $c.win.alert("비활성 종목은 변경처리 할 수 없습니다.");
        dts_BefIsuInfo.setCellData(nRow, "CHK", "F");
        return;
    }
};

/**
 * @method
 * @name checkAll
 * @description 전체 체크
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.checkAll = function(bCheck) {
    grd_BefIsuInfo.ReDraw = false;
    for (let nRow = 1; nRow <= dts_BefIsuInfo.getRowCount(); nRow++) {
        if (dts_BefIsuInfo.getCellData(nRow, "LIST_STAT_CD") === "Y") {

        } else if (dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") !== "Y" && dts_BefIsuInfo.getCellData(nRow, "ACTIV_TP_CD") !== "1") {

        } else {
            if (dts_BefIsuInfo.getCellData(nRow, "KIND") === "주식워런트" || dts_BefIsuInfo.getCellData(nRow, "KIND") === "ETN") {

            } else {
                scwin.check(nRow, bCheck, false);
            }
        }
    }
    grd_BefIsuInfo.ReDraw = true;
};

/**
 * @method
 * @name check
 * @description 전송여부가 N인 경우 체크박스 체크
 * @param {*} nRow nRow
 * @param {*} bCheck bCheck
 * @param {*} bMsgShow bMsgShow
 * @returns {void}
 * @hidden N
 */
scwin.check = function(nRow, bCheck, bMsgShow) {
    dts_BefIsuInfo.setCellData(nRow, "CHK", bCheck ? "T" : "F");
};

